CREATE TRIGGER RefHarbourRate_Version_Create
	ON RefHarbourRate
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT ZXF_PK, 'ZXF'
	FROM inserted
GO
CREATE TRIGGER RefHarbourRate_Version_Update
	ON RefHarbourRate
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON ZXF_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefHarbourRate_DataChangeHistory
	ON RefHarbourRate
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT ZXF_PK, 'ZXF' FROM inserted
	UNION
	SELECT ZXF_PK, 'ZXF' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefHarbourRate_DataProcessingResult_Delete
	ON RefHarbourRate
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.ZXF_PK
	END
GO
